import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[] f = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            f[i] = fs.nextInt();
        }
        List<Integer>[] adj = new ArrayList[n + 1];
        List<Integer>[] revAdj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
            revAdj[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            adj[a].add(b);
            revAdj[b].add(a);
        }

        // Forward BFS from all assignment nodes (f[i] == 1)
        boolean[] forwardReachable = new boolean[n + 1];
        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (f[i] == 1) {
                forwardReachable[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!forwardReachable[v]) {
                    forwardReachable[v] = true;
                    q.add(v);
                }
            }
        }

        // Reverse BFS from all use nodes (f[i] == 2)
        boolean[] reverseReachable = new boolean[n + 1];
        Queue<Integer> rq = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (f[i] == 2) {
                reverseReachable[i] = true;
                rq.add(i);
            }
        }
        while (!rq.isEmpty()) {
            int u = rq.poll();
            for (int v : revAdj[u]) {
                if (!reverseReachable[v]) {
                    reverseReachable[v] = true;
                    rq.add(v);
                }
            }
        }

        // Determine result
        int[] result = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            result[i] = (forwardReachable[i] && reverseReachable[i]) ? 1 : 0;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            sb.append(result[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private int readByte() throws IOException {
            if (ptr >= buflen) {
                buflen = in.read(buffer);
                ptr = 0;
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int x) {
            return x == ' ' || x == '\n' || x == '\r' || x == '\t' || x == -1;
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (isSpace(c)) c = readByte();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int val = 0;
            while (!isSpace(c)) {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -val : val;
        }
    }
}
