            revAdj[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            adj[a].add(b);
            revAdj[b].add(a);
        }

        boolean[] reachableFromAssign = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 1) {
                reachableFromAssign[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!reachableFromAssign[v]) {
                    reachableFromAssign[v] = true;
                    q.add(v);
                }
            }
        }

        boolean[] canReachUse = new boolean[n];
        Queue<Integer> q2 = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 2) {
                canReachUse[i] = true;
                q2.add(i);
            }
        }
        while (!q2.isEmpty()) {
            int u = q2.poll();
            for (int v : revAdj[u]) {
                if (!canReachUse[v]) {
                    canReachUse[v] = true;
                    q2.add(v);
                }
            }
        }

        boolean[] hasAssignOnPath = new boolean[n];
        Queue<Integer> q3 = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (reachableFromAssign[i] && f[i] == 1) {
                hasAssignOnPath[i] = true;
                q3.add(i);
            }
        }
        while (!q3.isEmpty()) {
            int u = q3.poll();
            for (int v : adj[u]) {
                if (reachableFromAssign[v] && !hasAssignOnPath[v]) {
                    if (f[v] == 1) {
                        continue;
                    }
                    hasAssignOnPath[v] = true;
                    q3.add(v);
                }
            }
        }

        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            if (reachableFromAssign[i] && canReachUse[i] && !hasAssignOnPath[i]) {
                result[i] = 1;
            } else {
                result[i] = 0;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(result[i]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() throws IOException {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() throws IOException {
            if (hasNextByte()) {
                return buffer[ptr++];
            }
            return -1;
        }

        private boolean isPrintableChar(int c) {
            return 32 < c;
        }

        public String next() throws IOException {
            int c = readByte();
            while (!isPrintableChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (isPrintableChar(c));
            return sb.toString();
        }

        public int nextInt() throws IOException {
            int num = 0;
            int c = readByte();
            while (!isPrintableChar(c)) {
                c = readByte();
            }
            boolean minus = false;
            if (c == '-') {
                minus = true;
                c = readByte();
            }
            do {
                if (c < '0' || c > '9') {
                    break;
                }
                num = num * 10 + (c - '0');
                c = readByte();
            } while (isPrintableChar(c));
            return minus ? -num : num;
        }
    }
}
