public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[] f = new int[n];
        for (int i = 0; i < n; i++) {
            f[i] = fs.nextInt();
        }
        List<Integer>[] adj = new ArrayList[n];
        List<Integer>[] radj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
            radj[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            adj[a].add(b);
            radj[b].add(a);
        }
        boolean[] forward = new boolean[n];
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 1) {
                forward[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!forward[v]) {
                    forward[v] = true;
                    q.add(v);
                }
            }
        }
        boolean[] backward = new boolean[n];
        Queue<Integer> q2 = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (f[i] == 2) {
                backward[i] = true;
                q2.add(i);
            }
        }
        while (!q2.isEmpty()) {
            int u = q2.poll();
            for (int v : radj[u]) {
                if (!backward[v]) {
                    backward[v] = true;
                    q2.add(v);
                }
            }
        }
        for (int i = 0; i < n; i++) {
            System.out.println((forward[i] && backward[i]) ? 1 : 0);
        }
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() throws IOException {
            if (ptr < buflen) return true;
            ptr = 0;
            buflen = in.read(buffer);
            return buflen > 0;
        }

        private int readByte() throws IOException {
            if (ptr < buflen) return buffer[ptr++];
            else {
                buflen = in.read(buffer);
                ptr = 0;
                return buflen > 0 ? buffer[ptr++] : -1;
            }
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        private static boolean isNumber(int c) {
            return c >= '0' && c <= '9';
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (!isNumber(c)) {
                c = readByte();
            }
            int val = 0;
            while (isNumber(c)) {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val;
        }
    }
}
