public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[] f = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            f[i] = fs.nextInt();
        }
        List<Integer>[] adj = new ArrayList[n + 1];
        List<Integer>[] revAdj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
            revAdj[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            adj[a].add(b);
            revAdj[b].add(a);
        }

        // Forward BFS from all assignment nodes (f[i] == 1)
        boolean[] forward = new boolean[n + 1];
        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (f[i] == 1) {
                forward[i] = true;
                q.add(i);
            }
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!forward[v]) {
                    forward[v] = true;
                    q.add(v);
                }
            }
        }

        // Backward BFS from all use nodes (f[i] == 2)
        boolean[] backward = new boolean[n + 1];
        Queue<Integer> q2 = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (f[i] == 2) {
                backward[i] = true;
                q2.add(i);
            }
        }
        while (!q2.isEmpty()) {
            int u = q2.poll();
            for (int v : revAdj[u]) {
                if (!backward[v]) {
                    backward[v] = true;
                    q2.add(v);
                }
            }
        }

        // Compute result
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (forward[i] && backward[i]) {
                sb.append(1).append('\n');
            } else {
                sb.append(0).append('\n');
            }
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private int read() throws IOException {
            if (buflen == -1) return -1;
            if (ptr >= buflen) {
                buflen = in.read(buffer);
                ptr = 0;
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') c = read();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }
    }
}
