                    backwardReachable[v] = true;
                    q2.add(v);
                }
            }
        }

        boolean[] assigned = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (f[i] == 1) assigned[i] = true;
        }

        boolean[] hasAssignment = new boolean[n + 1];
        Queue<Integer> q3 = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
